import java.util.Scanner;

public class Main {
    static final int N = 505;
    static int n, m, mod;
    static int[][] C = new int[N][N];
    static long[] f = new long[N], g = new long[N];
    static long[][] ff = new long[N][N], gg = new long[N][N];

    static void combine(long[] x, int y) {
        for (int i = 0; i < x.length; i++) {
            x[i] += y;
            if (x[i] >= mod) x[i] -= mod;
        }
    }

    static void combine(long[] x, long y) {
        for (int i = 0; i < x.length; i++) {
            x[i] += y;
            if (x[i] >= mod) x[i] -= mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = (f[j - 1] * f[i - j]) % mod;
                long val2 = C[i - 1][j - 1];
                long val3 = (long) (i + 1);
                long temp = (val1 * val2) % mod;
                temp = (temp * val3) % mod;
                combine(f, (int) temp);

                long val4 = (g[j - 1] * f[i - j]) % mod;
                long temp2 = (val4 * val2) % mod;
                temp2 = (temp2 * val3) % mod;
                combine(g, (int) temp2);

                long val5 = (g[i - j] * f[j - 1]) % mod;
                long temp3 = (val5 * val2) % mod;
                temp3 = (temp3 * val3) % mod;
                combine(g, (int) temp3);

                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                }
                long val6 = (f[j - 1] * f[i - j]) % mod;
                long temp4 = (val6 * val2) % mod;
                temp4 = (temp4 * s) % mod;
                combine(g, (int) temp4);
            }
        }

        ff[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == i) {
                    ff[i][j] = f[i];
                    gg[i][j] = g[i];
                    continue;
                }
                ff[i][j] = ff[i - 1][j];
                gg[i][j] = gg[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    long val1 = ff[i - k - 1][j - k];
                    long val2 = f[k];
                    long val3 = C[j][k];

                    long tempF = (val1 * val2) % mod;
                    tempF = (tempF * val3) % mod;
                    ff[i][j] = (ff[i][j] + tempF) % mod;

                    long val4 = ff[i - k - 1][j - k];
                    long val5 = g[k];
                    long tempG1 = (val4 * val5) % mod;
                    tempG1 = (tempG1 * val3) % mod;
                    gg[i][j] = (gg[i][j] + tempG1) % mod;

                    long val6 = gg[i - k - 1][j - k];
                    long tempG2 = (val6 * f[k]) % mod;
                    tempG2 = (tempG2 * val3) % mod;
                    gg[i][j] = (gg[i][j] + tempG2) % mod;
                }
            }
        }

        System.out.println(gg[n][m]);
        sc.close();
    }
}
